1: // 5-field cron (min hour dom mon dow), UTC only. Supports * lists ranges steps.
2: // ponytail: no seconds, no @daily aliases, no timezones — add when someone asks.
3: const BOUNDS = [
4:   [0, 59],
5:   [0, 23],
6:   [1, 31],
7:   [1, 12],
8:   [0, 7], // 7 = sunday, normalized to 0
9: ];
10: 
11: export function parseCron(expr) {
12:   const fields = String(expr).trim().split(/\s+/);
13:   if (fields.length !== 5) throw new Error(`need 5 fields (min hour day month weekday), got ${fields.length}`);
14:   return fields.map((field, i) => {
15:     const [lo, hi] = BOUNDS[i];
16:     const set = new Set();
17:     for (const part of field.split(',')) {
18:       const m = part.match(/^(\*|\d+(?:-\d+)?)(?:\/(\d+))?$/);
19:       if (!m || m[2] === '0') throw new Error(`bad field "${part}"`);
20:       const step = m[2] ? Number(m[2]) : 1;
21:       let [a, b] = m[1] === '*' ? [lo, hi] : m[1].split('-').map(Number);
22:       if (b === undefined) b = m[2] ? hi : a; // "5/10" means "5-59/10", plain "5" means just 5
23:       if (a < lo || b > hi || a > b) throw new Error(`"${part}" out of range ${lo}-${hi}`);
24:       for (let v = a; v <= b; v += step) set.add(i === 4 && v === 7 ? 0 : v);
25:     }
26:     return { set, star: field === '*' };
27:   });
28: }
