30: export function matches(parsed, date) {
31:   const [min, hour, dom, mon, dow] = parsed;
32:   if (!min.set.has(date.getUTCMinutes()) || !hour.set.has(date.getUTCHours()) || !mon.set.has(date.getUTCMonth() + 1)) return false;
33:   const domOk = dom.set.has(date.getUTCDate());
34:   const dowOk = dow.set.has(date.getUTCDay());
35:   // standard cron: when both day fields are restricted, either one matching fires
36:   return !dom.star && !dow.star ? domOk || dowOk : domOk && dowOk;
37: }
38: 
39: // Next matching minute strictly after fromMs, as epoch ms. Scans by day (skips
40: // non-matching days at midnight), 4 years max — catches "0 0 30 2 *" at deploy time.
41: export function nextRun(parsed, fromMs) {
42:   const [min, hour, dom, mon, dow] = parsed;
43:   let t = Math.floor(fromMs / 60000) * 60000 + 60000;
44:   for (let guard = 0; guard < 4 * 366 * 1440; guard++, t += 60000) {
45:     const d = new Date(t);
46:     const domOk = dom.set.has(d.getUTCDate());
47:     const dowOk = dow.set.has(d.getUTCDay());
48:     const dayOk = mon.set.has(d.getUTCMonth() + 1) && (!dom.star && !dow.star ? domOk || dowOk : domOk && dowOk);
49:     if (!dayOk) {
50:       t = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + 1) - 60000;
51:       continue;
52:     }
53:     if (min.set.has(d.getUTCMinutes()) && hour.set.has(d.getUTCHours())) return t;
54:   }
55:   throw new Error('never fires (checked 4 years ahead)');
56: }

