214: // Shared by the manual /api/runs path and the cron tick. startedBy = email or "cron".
215: // Marks the run failed and rethrows if the machine won't start.
216: async function startRun(env, app, startedBy, baseUrl) {
217:   const runId = 'r-' + randomHex(6);
218:   await env.DB.prepare('INSERT INTO runs (run_id, app_id, started_by) VALUES (?, ?, ?)').bind(runId, app.id, startedBy).run();
219:   const runToken = await sign({ t: 'run', run: runId, exp: now() + 6 * 3600 }, env.MASTER_KEY);
220:   try {
221:     await startMachine(env, app.fly_app, {
222:       image: app.image,
223:       auto_destroy: true,
224:       restart: { policy: 'no' },
225:       guest: { cpu_kind: 'shared', cpus: 1, memory_mb: 256 }, // ponytail: fixed size; read memory from small.toml when a job needs more
226:       env: {
227:         SMALL_RUN_ID: runId,
228:         SMALL_RUN_TOKEN: runToken,
229:         SMALL_USER: startedBy,
230:         SMALL_API: baseUrl,
231:         ...(startedBy === 'cron' ? { SMALL_TRIGGER: 'cron' } : {}),
232:       },
233:     });
234:   } catch (e) {
235:     await env.DB.prepare("UPDATE runs SET status = 'failed', finished_at = datetime('now') WHERE run_id = ?").bind(runId).run();
236:     throw e;
237:   }
238:   return runId;
239: }
