294: // Called by runner.py with the per-run token — not a CLI token.
295: async function apiRunLog(req, env, runId) {
296:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
297:   const p = m && (await verify(m[1], env.MASTER_KEY));
298:   if (!p || p.t !== 'run' || p.run !== runId) return json({ error: 'bad run token' }, 401);
299:   const { lines = [], exitCode } = await req.json();
300:   if (lines.length) {
301:     // ponytail: MAX(seq) is race-free only because one runner posts batches sequentially
302:     const { m: maxSeq } = await env.DB.prepare('SELECT COALESCE(MAX(seq), -1) AS m FROM run_logs WHERE run_id = ?').bind(runId).first();
303:     let seq = maxSeq;
304:     const stmt = env.DB.prepare('INSERT INTO run_logs (run_id, seq, line) VALUES (?, ?, ?)');
305:     await env.DB.batch(lines.map((l) => stmt.bind(runId, ++seq, String(l))));
306:   }
307:   if (exitCode !== undefined && exitCode !== null) {
308:     await env.DB.prepare("UPDATE runs SET status = ?, exit_code = ?, finished_at = datetime('now') WHERE run_id = ?")
309:       .bind(exitCode === 0 ? 'finished' : 'failed', exitCode, runId)
310:       .run();
311:   }
312:   return json({ ok: true });
313: }
