321: async function loginPage(req, env, baseUrl) {
322:   const url = new URL(req.url);
323:   const next = url.searchParams.get('next') || '/';
324:   if (req.method === 'POST') {
325:     const form = await req.formData();
326:     const email = String(form.get('email') || '').toLowerCase().trim();
327:     if (!email.includes('@')) return html('<p>Enter a valid work email.</p><a href="javascript:history.back()">back</a>', 400);
328:     const magic = await sign({ t: 'magic', email, next, exp: now() + 900 }, env.MASTER_KEY);
329:     const link = `${baseUrl}/auth?token=${encodeURIComponent(magic)}`;
330:     const sent = await sendEmail(env, email, 'Your small sign-in link', `Sign in: ${link}\nExpires in 15 minutes.`);
331:     if (sent) return html(`<h2>Check your inbox</h2><p>We sent a sign-in link to <b>${email}</b>.</p>`);
332:     if (!env.TEST_BYPASS_SECRET) return html('<p>Email is not configured on this control plane.</p>', 503);
333:     return html(`<h2>Test instance</h2><p>Dev sign-in link:</p><p><a href="${link}">${link}</a></p>`);
334:   }
335:   return html(`<h2>Sign in to small</h2><form method=post><input name=email type=email placeholder=[REDACTED] required autofocus> <button>Send link</button></form>`);
336: }
