338: async function authRedirect(req, env) {
339:   const token = new URL(req.url).searchParams.get('token');
340:   const p = await verify(token, env.MASTER_KEY);
341:   if (!p || p.t !== 'magic') return html('<p>Link expired or invalid. <a href="/login">Try again</a>.</p>', 401);
342:   const sess = await sign({ t: 'sess', email: p.email, exp: now() + SESSION_TTL }, env.MASTER_KEY);
343:   return new Response(null, { status: 302, headers: { Location: p.next || '/', 'Set-Cookie': sessionCookie(sess) } });
344: }
345: 
346: // Test bypass: mint a session without email. Enabled only when TEST_BYPASS_SECRET is set.
347: async function testSession(req, env) {
348:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'not enabled' }, 404);
349:   const { email, secret } = await req.json();
350:   if (secret !== env.TEST_BYPASS_SECRET) return json({ error: 'bad secret' }, 401);
351:   const sess = await sign({ t: 'sess', email: email.toLowerCase(), exp: now() + SESSION_TTL }, env.MASTER_KEY);
352:   return json({ session: sess }, 200);
353: }
354: 
355: // ---------- Router/proxy ----------
356: 
357: async function proxyApp(req, env, org, name, rest, baseUrl) {
358:   const sess = await sessionOf(req, env);
359:   const prefix = `/a/${org}/${name}`;
360:   if (!sess) {
361:     if (req.method !== 'GET') return json({ error: 'login required' }, 401);
362:     return new Response(null, { status: 302, headers: { Location: `${baseUrl}/login?next=${encodeURIComponent(prefix + '/')}` } });
363:   }
364:   const app = await appRow(env, org, name);
365:   if (!app) return html(`<p>No app <b>${name}</b> here.</p>`, 404);
366:   if (!(await canView(env, app, sess.email))) return html(`<p><b>${sess.email}</b> does not have access to <b>${name}</b>. Ask the owner to run <code>small share ${sess.email}</code>.</p>`, 403);
367:   if (rest === '') return new Response(null, { status: 301, headers: { Location: `${prefix}/` } }); // relative URLs need the trailing slash
368: 
369:   const origin = `https://${app.fly_app}.fly.dev`;
370:   const target = new URL(req.url);
371:   const headers = new Headers(req.headers);
372:   headers.delete('Cookie'); // the app never sees the session
373:   headers.delete('X-Small-Session');
374:   headers.set('X-Small-User', sess.email);
375:   headers.set('X-Small-Org', org);
376:   headers.set('X-Small-Proxy', app.proxy_secret);
377:   let resp;
378:   for (let attempt = 0; ; attempt++) {
379:     resp = await fetch(`${origin}${rest}${target.search}`, {
380:       method: req.method,
381:       headers,
382:       body: ['GET', 'HEAD'].includes(req.method) ? undefined : req.body,
383:       redirect: 'manual',
384:     });
385:     // Fly answers 502/503 while a scaled-to-zero machine wakes (~30s for torch-heavy apps);
386:     // hold safe-to-repeat requests instead of showing the browser a Bad Gateway.
387:     if (![502, 503].includes(resp.status) || !['GET', 'HEAD'].includes(req.method) || attempt >= 9) break;
388:     await new Promise((r) => setTimeout(r, 5000));
389:   }
390:   const out = new Headers(resp.headers);
391:   const loc = out.get('Location');
392:   if (loc && loc.startsWith('/') && !loc.startsWith('/a/')) out.set('Location', prefix + loc); // path-based hosting: re-prefix app redirects
393:   return new Response(resp.body, { status: resp.status, headers: out });
394: }
