396: export default {
397:   async fetch(req, env, ctx) {
398:     const url = new URL(req.url);
399:     const baseUrl = `${url.protocol}//${url.host}`;
400:     const path = url.pathname;
401:     try {
402:       if (path === '/api/cli/login' && req.method === 'POST') return await apiLogin(req, env);
403:       if (path === '/api/cli/verify' && req.method === 'POST') return await apiVerify(req, env);
404:       if (path === '/api/runtime/aws-creds' && req.method === 'POST') return await apiAwsCreds(req, env);
405:       if (path.startsWith('/api/')) {
406:         const runLog = path.match(/^\/api\/runs\/([\w-]+)\/log$/);
407:         if (runLog && req.method === 'POST') return await apiRunLog(req, env, runLog[1]); // runner auth, not CLI auth
408:         const user = await cliAuth(req, env);
409:         if (!user) return json({ error: 'run small login first' }, 401);
410:         if (path === '/api/deploy' && req.method === 'POST') return await apiDeploy(req, env, ctx, user, baseUrl);
411:         if (path === '/api/image' && req.method === 'POST') return await apiImage(req, env, user);
412:         if (path === '/api/runs' && req.method === 'POST') return await apiRunStart(req, env, user, baseUrl);
413:         if (path === '/api/runs' && req.method === 'GET') return await apiRunsList(req, env, user);
414:         const runGet = path.match(/^\/api\/runs\/([\w-]+)$/);
415:         if (runGet && req.method === 'GET') return await apiRunGet(req, env, user, runGet[1]);
416:         if (path === '/api/schedule' && req.method === 'POST') return await apiSchedulePause(req, env, user);
417:         if (path === '/api/share' && req.method === 'POST') return await apiShare(req, env, user);
418:         if (path === '/api/apps' && req.method === 'GET') return await apiApps(env, user);
419:         if (path === '/api/logs' && req.method === 'GET') return await apiLogs(req, env, user);
420:         if (path === '/api/review' && req.method === 'GET') return await apiReview(req, env, user);
421:         return json({ error: 'no such endpoint' }, 404);
422:       }
423:       if (path === '/login') return await loginPage(req, env, baseUrl);
424:       if (path === '/auth') return await authRedirect(req, env);
425:       if (path === '/test/session' && req.method === 'POST') return await testSession(req, env);
426:       const m = path.match(/^\/a\/([a-z0-9-]+)\/([a-z0-9-]+)(\/.*)?$/);
427:       if (m) return await proxyApp(req, env, m[1], m[2], m[3] || '', baseUrl);
428:       if (path === '/') return html('<h2>small</h2><p>Deploy a Python app behind a login in one command: <code>npm i -g small-deploy</code></p>');
429:       return html('<p>Not found.</p>', 404);
430:     } catch (err) {
431:       return json({ error: `internal: ${err.message}` }, 500);
432:     }
433:   },
434: 
435:   // Cron trigger fires every minute (wrangler.jsonc). scheduledTime is the tick's
436:   // nominal minute even when delivery is late; last_scheduled_at pins each fired
437:   // minute so a duplicate or late tick never double-fires.
438:   // ponytail: no catch-up after downtime — a missed minute is just missed.
439:   async scheduled(event, env, ctx) {
440:     const tick = Math.floor(event.scheduledTime / 60000) * 60; // unix seconds, floored to the minute
441:     const { results } = await env.DB.prepare(
442:       "SELECT * FROM apps WHERE kind = 'job' AND schedule IS NOT NULL AND schedule_paused = 0 AND image IS NOT NULL"
443:     ).all();
444:     for (const app of results) {
445:       let parsed;
446:       try {
447:         parsed = parseCron(app.schedule);
448:       } catch {
449:         continue; // validated at deploy; a bad legacy row must not kill the whole tick
450:       }
451:       if (!matches(parsed, new Date(tick * 1000)) || (app.last_scheduled_at || 0) >= tick) continue;
452:       await env.DB.prepare('UPDATE apps SET last_scheduled_at = ? WHERE id = ?').bind(tick, app.id).run();
453:       // ponytail: a run whose machine died before posting an exit code stays 'running'
454:       // and blocks cron forever; add a max-age cutoff when it bites.
455:       const running = await env.DB.prepare("SELECT 1 AS x FROM runs WHERE app_id = ? AND status = 'running' LIMIT 1").bind(app.id).first();
456:       if (running) {
457:         await env.DB.prepare(
458:           "INSERT INTO runs (run_id, app_id, started_by, status, reason, finished_at) VALUES (?, ?, 'cron', 'skipped', 'previous run still active', datetime('now'))"
459:         ).bind('r-' + randomHex(6), app.id).run();
460:         continue;
461:       }
462:       try {
463:         await startRun(env, app, 'cron', env.BASE_URL);
464:       } catch (e) {
465:         console.error(`cron: ${app.org}/${app.name}: ${e.message}`); // run row already marked failed
466:       }
467:     }
468:   },
469: };

