1: #!/usr/bin/env node
2: 'use strict';
3: const fs = require('fs');
4: const path = require('path');
5: const readline = require('node:readline/promises');
6: const { detect } = require('../lib/detect');
7: const { init } = require('../lib/init');
8: const { write, writeFlyToml } = require('../lib/generate');
9: const { call, apiBase } = require('../lib/api');
10: const { buildBundle } = require('../lib/bundle');
11: const config = require('../lib/config');
12: const envfile = require('../lib/envfile');
13: const fly = require('../lib/fly');
14: 
15: const [cmd, ...rest] = process.argv.slice(2);
16: const flags = { _: [] };
17: for (let i = 0; i < rest.length; i++) {
18:   if (rest[i].startsWith('--')) {
19:     const key = rest[i].slice(2);
20:     flags[key] = rest[i + 1] && !rest[i + 1].startsWith('--') ? rest[++i] : true;
21:   } else {
22:     flags._.push(rest[i]);
23:   }
24: }
