118: const commands = {
119:   async login() {
120:     if (flags.api) config.save({ ...config.load(), apiBase: flags.api });
121:     const email = flags.email || (await ask('work email: '));
122:     const res = await call('POST', '/api/cli/login', { email }, { auth: false });
123:     if (res.devCode) console.log(`(dev) code: ${res.devCode}`);
124:     else console.log(`✓ code sent to ${email}`);
125:     const code = flags.code || (await ask('6-digit code: '));
126:     const v = await call('POST', '/api/cli/verify', { challenge: res.challenge, code }, { auth: false });
127:     config.save({ ...config.load(), token: v.token, email: v.email, org: v.org, apiBase: apiBase() });
128:     console.log(`✓ logged in as ${v.email} (org: ${v.org})`);
129:   },
130: 
131:   async init() {
132:     if (!init(process.cwd(), { force: !!flags.force })) process.exitCode = 1;
133:   },
134: 
135:   async deploy() {
136:     const dir = process.cwd();
137:     if (!fs.existsSync(path.join(dir, 'small.toml')) && !init(dir)) {
138:       process.exitCode = 1;
139:       return;
140:     }
141:     const app = detect(dir, flags);
142:     console.log(`✓ entry: ${app.entry} (${app.framework}) via ${app.via}`);
143: 
144:     const envPath = path.resolve(dir, typeof flags.env === 'string' ? flags.env : '.env');
145:     const secrets = envfile.parse(envPath);
146:     const required = (app.config.secrets && app.config.secrets.required) || [];
147:     const missing = required.filter((k) => !(k in secrets));
148:     if (missing.length) throw new Error(`missing secrets: ${missing.join(', ')} — add them to ${envPath}`);
149: 
150:     write(dir, app);
151:     const review = buildBundle(dir, app.entry, secrets);
152:     const visibility = (app.config.access && app.config.access.visibility) || undefined;
153:     const storage = app.config.storage;
154:     let sizeGb;
155:     if (storage) {
156:       const m = /^(\d+)\s*gb$/i.exec(String(storage.size || '1GB'));
157:       if (!m) throw new Error('storage.size must be whole gigabytes, like "1GB"');
158:       sizeGb = Number(m[1]);
159:     }
160:     const awsRoleArn = (app.config.aws && app.config.aws.role_arn) || undefined;
161:     const kind = app.config.kind === 'job' ? 'job' : 'server';
162:     const schedule = app.config.schedule;
163:     const d = await call('POST', '/api/deploy', {
164:       name: app.name,
165:       framework: app.framework,
166:       visibility,
167:       awsRoleArn,
168:       kind,
169:       review,
170:       storage: storage ? { sizeGb } : undefined,
171:       schedule: kind === 'job' ? schedule || null : undefined, // null clears a removed schedule
172:     });
173:     if (!d.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
174:     if (storage && !d.volumeRegion) throw new Error('control plane does not support [storage] yet — redeploy the worker');
175:     writeFlyToml(dir, d.flyApp, app.config.memory, storage ? { path: storage.path || '/data', region: d.volumeRegion } : undefined);
176:     if (storage) console.log(`✓ storage: ${storage.path || '/data'} (${sizeGb}GB volume in ${d.volumeRegion}, survives redeploys)`);
177: 
178:     if (kind === 'job') {
179:       if (schedule) {
180:         if (!d.nextRun && !d.schedulePaused) throw new Error('control plane does not support schedule yet — redeploy the worker');
181:         const next = d.schedulePaused
182:           ? `paused — small schedule resume ${app.name}`
183:           : `next run ${new Date(d.nextRun).toISOString().slice(0, 16).replace('T', ' ')}`;
184:         console.log(`✓ schedule: ${schedule} (UTC) · ${next}`);
185:       }
186:       // jobs: build + register the image, start nothing — the control plane starts machines per run
187:       fly.setSecrets(d.flyApp, d.flyToken, secrets);
188:       const image = fly.buildImage(d.flyApp, d.flyToken, dir, `v${Date.now()}`);
189:       await call('POST', '/api/image', { app: app.name, image });
190:       console.log(`✓ built ${app.name} — start it with: small run ${app.name}`);
191:       return;
192:     }
193: 
194:     // gradio builds asset/API URLs from its root; behind the path proxy that must be the public URL
195:     const rootPath = app.framework === 'gradio' ? { GRADIO_ROOT_PATH: d.url.replace(/\/$/, '') } : {};
196:     // [aws] role: guard fetches STS session creds from the control plane at boot
197:     const cpUrl = awsRoleArn ? { SMALL_CP_URL: apiBase() } : {};
198:     fly.setSecrets(d.flyApp, d.flyToken, { SMALL_PROXY_SECRET: d.proxySecret, ...rootPath, ...cpUrl, ...secrets });
199:     if (awsRoleArn) console.log(`✓ aws role: ${awsRoleArn} (STS via control plane)`);
200:     fly.deploy(d.flyApp, d.flyToken, dir);
201: 
202:     console.log(`✓ deployed → ${d.url}`);
203:     const { org } = config.load();
204:     console.log(visibility === 'private' ? '✓ login required · explicit members only' : `✓ login required · anyone @${org}`);
205:     if (d.reviewStarted) await reviewAfterDeploy(app.name, d.reviewedAt);
206:     else console.log('review: unavailable');
207:   },
208: 
209:   async review() {
210:     const name = flags._[0] || appName(process.cwd());
211:     const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
212:     if (!res.review) return console.log('review: unavailable — no reviewed deploy yet');
213:     if (flags.diff) printDiff(res);
214:     else printReport(res);
215:   },
216: 
217:   async run() {
218:     const name = flags._[0] || appName(process.cwd());
219:     const { runId } = await call('POST', '/api/runs', { app: name });
220:     console.log(`run: ${runId}`);
221:     let cursor = -1;
222:     for (;;) {
223:       const r = await call('GET', `/api/runs/${encodeURIComponent(runId)}?after=${cursor}`);
224:       for (const line of r.lines) console.log(line);
225:       if (r.lines.length) cursor = r.cursor;
226:       if (r.status !== 'running' && !r.lines.length) {
227:         console.log(r.exitCode === 0 ? `✓ finished (exit ${r.exitCode})` : `✗ failed (exit ${r.exitCode})`);
228:         process.exitCode = r.exitCode === 0 ? 0 : 1;
229:         return;
230:       }
231:       await new Promise((res) => setTimeout(res, 1000));
232:     }
233:   },
234: 
235:   async runs() {
236:     const name = flags._[0] || appName(process.cwd());
237:     const { runs } = await call('GET', `/api/runs?app=${encodeURIComponent(name)}`);
238:     if (!runs.length) return console.log(`no runs yet — small run ${name}`);
239:     for (const r of runs) {
240:       // sqlite datetime('now') strings are UTC without a zone marker
241:       const dur = r.status === 'skipped' ? '—' : r.finished_at ? `${Math.round((new Date(r.finished_at + 'Z') - new Date(r.started_at + 'Z')) / 1000)}s` : '…';
242:       const by = r.started_by === 'cron' ? '⏱ cron' : r.started_by;
243:       console.log(`${r.run_id}  ${r.status}  ${dur}  ${by}  ${r.started_at}${r.reason ? `  (${r.reason})` : ''}`);
244:     }
245:   },
246: 
247:   async schedule() {
248:     const action = flags._[0];
249:     if (!['pause', 'resume'].includes(action)) throw new Error('usage: small schedule <pause|resume> [app]');
250:     const name = flags._[1] || appName(process.cwd());
251:     const res = await call('POST', '/api/schedule', { app: name, paused: action === 'pause' });
252:     console.log(`✓ schedule ${res.paused ? 'paused' : 'resumed'} for ${name} (${res.schedule})`);
253:   },
254: 
255:   async logs() {
256:     const arg = flags._[0];
257:     if (arg && arg.startsWith('r-')) {
258:       const r = await call('GET', `/api/runs/${encodeURIComponent(arg)}?after=-1`);
259:       for (const line of r.lines) console.log(line);
260:       return;
261:     }
262:     const name = arg || appName(process.cwd());
263:     const res = await call('GET', `/api/logs?app=${encodeURIComponent(name)}`);
264:     if (!res.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
265:     fly.logs(res.flyApp, res.flyToken);
266:   },
267: 
268:   async share() {
269:     const email = flags._[0];
270:     if (!email || !email.includes('@')) throw new Error('usage: small share <email> [--edit] [--app name]');
271:     const name = appName(process.cwd());
272:     const res = await call('POST', '/api/share', { app: name, email, role: flags.edit ? 'edit' : 'view' });
273:     console.log(`✓ ${res.email} can ${res.role} ${res.app}`);
274:   },
275: 
276:   async list() {
277:     const { apps } = await call('GET', '/api/apps');
278:     if (!apps.length) return console.log('no apps yet — run small deploy');
279:     for (const a of apps) console.log(`${a.name}  ${a.visibility}  owner:${a.owner_email}`);
280:   },
281: 
282: };
